let speechAvailable=!!window.speechSynthesis, segmentActive=false, segmentFrame=0, localAudio=false;
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({songs:allSongs,favorites,mastered,currentId}));}catch{toast('浏览器存储已满或不可用，修改暂时只保留在本页。');}}
const dbPromise=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('No storage'));return;}const req=indexedDB.open('kotoba-media',1);req.onupgradeneeded=()=>{const db=req.result;db.createObjectStore('audio',{keyPath:'id'});db.createObjectStore('recordings',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
dbPromise.catch(()=>{});
async function dbCall(store, method, value){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction(store,method==='get'||method==='getAll'?'readonly':'readwrite');const req=tx.objectStore(store)[method](value);let result;req.onsuccess=()=>{result=req.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Storage aborted'));});}
function setPlaying(value){playing=value;document.querySelector('.practice-panel').classList.toggle('playing',value);$('listen').querySelector('span').textContent=value?'停止播放':(mode==='read'?'听本句朗读':song().demo&&!localAudio?'听原创钢琴旋律':'听本句歌曲片段');}
function stopPlayback(){operation++;clearTimeout(speechTimer);if(speechAvailable)speechSynthesis.cancel();segmentActive=false;cancelAnimationFrame(segmentFrame);$('song-audio').pause();setPlaying(false);}
function setStatus(text){$('practice-status').textContent=text;}
function cleanToken(t){return t.replace(/[.,!?。！？、;:]+$/u,'');}
function getWord(token){const found=(line().words||[]).find(w=>w.term===token.text||w.term===cleanToken(token.text));return found || {term:cleanToken(token.text),reading:token.reading,meaning:'这句还没有录入这个词的中文释义。',usage:'点击「编辑本句」，可以添加词义、用法和例句。'};}
function selectWord(word){currentWord=word;document.querySelectorAll('.lyric-token').forEach(b=>b.classList.toggle('active',b.dataset.term===word.term));$('word-term').textContent=word.term;$('word-reading').textContent=showReading?word.reading||'':'';$('word-meaning').textContent=word.meaning||'暂未填写词义';$('word-usage').textContent=word.usage||'暂未填写用法';$('word-example').replaceChildren();$('word-example').hidden=!word.example;if(word.example){$('word-example').append(el('div','',word.example),el('small','',word.exampleTranslation||''));}updateFavorite();}
function updateFavorite(){const saved=currentWord&&favorites.some(w=>w.term===currentWord.term&&w.lang===song().lang);$('save-word').setAttribute('aria-pressed',String(!!saved));$('save-word').setAttribute('aria-label',saved?'取消收藏当前词语':'收藏当前词语');}
function renderLine(){const s=song(),l=line();$('breadcrumb-title').textContent=s.title;$('language-tag').textContent=langLabels[s.lang]+' · '+({'ja-JP':'JAPANESE','en-US':'ENGLISH','ko-KR':'KOREAN'}[s.lang]);$('song-kind').textContent=s.demo?'原创学习示例':s.titleOnly?'优先学习曲目':'我的学习曲目';$('song-title').textContent=s.title;$('song-artist').textContent=s.artist+(s.id==='lilac'?' · 紫丁香':'');const done=s.lines.reduce((n,_,i)=>n+(mastered[s.id+':'+i]?1:0),0);$('progress-label').textContent=s.titleOnly?'从歌名开始认识这首歌':`已学会 ${done} / ${s.lines.length} 句`;$('line-counter').textContent=String(lineIndex+1).padStart(2,'0')+' / '+String(s.lines.length).padStart(2,'0');$('sentence-label').textContent=s.titleOnly?'歌名学习卡 · 非歌词':s.demo?'原创示例 · 第 '+(lineIndex+1)+' 句':'第 '+(lineIndex+1)+' 句';
  const tokens=parseAnnotated(l.text),content=$('lyric-line');content.replaceChildren();content.lang=s.lang;content.classList.toggle('hide-reading',!showReading);
  tokens.forEach(t=>{if(t.space){content.append(document.createTextNode(s.lang==='ja-JP'?' ':t.text));return;}const b=el('button','lyric-token');b.type='button';const word=getWord(t);b.dataset.term=word.term;b.setAttribute('aria-label',t.text+'：查看词义');if(t.reading){const ruby=el('ruby');ruby.append(document.createTextNode(t.text),el('rt','',t.reading));b.append(ruby);}else b.textContent=t.text;b.onclick=()=>selectWord(word);content.append(b);});
  $('reading-line').textContent=l.reading||'';$('reading-line').hidden=!showReading||s.lang==='ja-JP'||!l.reading;$('translation-wrap').hidden=!showTranslation;$('translation-text').textContent=l.translation||'尚未填写翻译，可在「编辑本句」中添加。';$('sentence-note').textContent=l.note||'先听自然朗读，点词理解意思，再跟着歌曲片段练习。';$('note-title').textContent=s.titleOnly?'这首歌，从这里开始':'读音与学习提示';$('setup-card').hidden=!s.titleOnly;$('master-line').classList.toggle('mastered',!!mastered[s.id+':'+lineIndex]);$('master-line').querySelector('span').textContent=mastered[s.id+':'+lineIndex]?'已学会':'我学会了';$('nav-progress').textContent=(lineIndex+1)+' / '+s.lines.length;$('prev-line').disabled=lineIndex===0;$('next-line').disabled=lineIndex===s.lines.length-1;$('sentence-count').textContent=s.lines.length+' 句';$('segment-start').value=l.start??0;$('segment-end').value=l.end??'';
  $('sentence-list').replaceChildren();s.lines.forEach((l,i)=>{const b=el('button','sentence-item'+(i===lineIndex?' active':''));b.append(el('span','number',String(i+1).padStart(2,'0')));const short=el('span','sentence-short',plainText(l.text));short.append(el('small','',l.translation||'待添加翻译'));b.append(short);if(mastered[s.id+':'+i])b.append(icon('check'));b.onclick=()=>changeLine(i);$('sentence-list').append(b);});selectWord(l.words?.[0]||getWord(tokens.find(t=>!t.space)||{text:plainText(l.text)}));updateMode();
}
function changeLine(i){stopPlayback();cancelRecording();lineIndex=i;setStatus('');$('latest-recording').hidden=true;renderLine();}
async function chooseSong(id){stopPlayback();cancelRecording();currentId=id;lineIndex=0;persist();setStatus('');$('latest-recording').hidden=true;renderLine();showView('learn');await loadAudio();}
function showView(view){if(view!=='learn'){stopPlayback();cancelRecording();}currentView=view;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==view+'-view');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='library')renderLibrary();if(view==='vocab')renderVocab();if(view==='recordings')renderRecordings();window.scrollTo({top:0,behavior:'instant'});}
function renderLibrary(){$('library-grid').replaceChildren();allSongs.forEach(s=>{const b=el('button','library-card'),cover=el('span','mini-cover',s.lang==='ja-JP'?'✳':s.lang==='en-US'?'☀':'✦'),info=el('div');info.append(el('span','tag',langLabels[s.lang]+(s.demo?' · 原创示例':'')),el('h3','',s.title),el('p','',s.artist),el('p','',s.titleOnly?'歌名学习卡 · 待导入歌词':s.lines.length+' 句学习卡'));b.append(cover,info,icon('chevron'));b.onclick=()=>chooseSong(s.id);$('library-grid').append(b);});}
function empty(container,title,text,symbol){const n=el('div','empty-state');n.append(el('span','',symbol),el('h3','',title),el('p','',text));container.append(n);}
function renderVocab(){const root=$('vocab-list');root.replaceChildren();if(!favorites.length){empty(root,'把喜欢的词，留在这里','学习时点一下词义卡右上角的心形，就能收藏。','♡');return;}favorites.forEach(w=>{const c=el('article','collection-card');c.append(el('small','',langLabels[w.lang]+' · '+w.songTitle),el('h3','',w.term),el('small','',w.reading||''),el('p','',w.meaning),el('p','',w.usage||''));if(w.example)c.append(el('p','example',w.example+' '+(w.exampleTranslation||'')));const buttons=el('div','collection-actions');const read=el('button','text-button','听读音');read.onclick=()=>speak(w.term,w.lang,false);const remove=el('button','text-button','取消收藏');remove.onclick=()=>{favorites=favorites.filter(x=>!(x.term===w.term&&x.lang===w.lang));persist();renderVocab();updateFavorite();};buttons.append(read,remove);c.append(buttons);root.append(c);});}
const galleryURLs=[];
async function renderRecordings(){const root=$('recordings-list');root.replaceChildren(el('p','muted','正在读取录音…'));try{storedRecordings=await dbCall('recordings','getAll');}catch{root.replaceChildren();empty(root,'本浏览器无法保存录音','本次录音仍可在练习页回听和下载。','♪');return;}if(currentView!=='recordings')return;galleryURLs.splice(0).forEach(u=>URL.revokeObjectURL(u));root.replaceChildren();if(!storedRecordings.length){empty(root,'你的第一段练唱，等你开口','打开学习卡，点击「录下我的练唱」。','♪');return;}storedRecordings.sort((a,b)=>b.created-a.created).forEach(r=>{const c=el('article','collection-card');c.append(el('small','',new Date(r.created).toLocaleString('zh-CN')),el('h3','',r.title),el('p','',r.text));const url=URL.createObjectURL(r.blob);galleryURLs.push(url);const player=el('audio');player.controls=true;player.src=url;c.append(player);const actions=el('div','collection-actions'),download=el('a','text-button','下载录音 ↓');download.href=url;download.download='kotoba-'+r.created+recordingExtension(r.blob.type);const remove=el('button','text-button','删除录音');remove.onclick=async()=>{try{await dbCall('recordings','delete',r.id);renderRecordings();}catch{toast('删除失败，请重试。');}};actions.append(download,remove);c.append(actions);root.append(c);});}
function updateMode(){$('mode-read').classList.toggle('active',mode==='read');$('mode-song').classList.toggle('active',mode==='song');$('mode-read').setAttribute('aria-pressed',String(mode==='read'));$('mode-song').setAttribute('aria-pressed',String(mode==='song'));$('mode-description').textContent=mode==='read'?'设备语音朗读，听清词语的自然读音。':song().demo&&!localAudio?'原创钢琴旋律辅助，非人声演唱。':'播放你导入的原唱片段，听歌曲中的唱法。';setPlaying(playing);$('loop').setAttribute('aria-pressed',String(looping));}
async function speak(text,lang,repeat=false){stopPlayback();const ticket=operation;if(!speechAvailable){setStatus('当前浏览器不支持语音朗读，请用手机 Safari 或 Chrome 尝试。');return;}let voices=speechSynthesis.getVoices();if(!voices.length){await new Promise(resolve=>setTimeout(resolve,250));voices=speechSynthesis.getVoices();}if(ticket!==operation)return;const voice=voices.find(v=>v.lang.replace('_','-').toLowerCase()===lang.toLowerCase())||voices.find(v=>v.lang.toLowerCase().startsWith(lang.split('-')[0]));if(!voice){setStatus('设备没有可用的'+langLabels[lang]+'语音，请在系统语音设置中安装对应语言。');return;}const utterance=new SpeechSynthesisUtterance(text);utterance.lang=lang;utterance.voice=voice;utterance.rate=Number($('speed').value);utterance.onstart=()=>{if(ticket===operation)setPlaying(true);};utterance.onend=()=>{if(ticket!==operation)return;setPlaying(false);if(repeat&&looping&&mode==='read')speechTimer=setTimeout(()=>speak(text,lang,true),800);};utterance.onerror=e=>{if(ticket!==operation||e.error==='canceled'||e.error==='interrupted')return;setPlaying(false);setStatus('朗读未成功（'+e.error+'），请检查设备语音设置。');};setStatus('');speechSynthesis.speak(utterance);}
function startSegment(){const a=$('song-audio'),l=line();if(!audioURL){setStatus('先导入歌曲音频，再为本句设置起止时间。');$('audio-input').click();return;}if(!validSegment(Number(l.start),Number(l.end),a.duration)||l.end===null){setStatus('请在「我的歌曲音频」里设置有效的本句起止时间。');$('segment-start').focus();return;}stopPlayback();const ticket=operation;setStatus('');a.currentTime=l.start;a.playbackRate=Number($('speed').value);a.preservesPitch=true;segmentActive=true;setPlaying(true);a.play().catch(()=>{if(ticket!==operation)return;segmentActive=false;setPlaying(false);setStatus('无法播放音频，请检查文件格式，或重新点击播放。');});const tick=()=>{if(!segmentActive||ticket!==operation)return;if(a.currentTime>=l.end-.035){if(looping){a.currentTime=l.start;if(a.paused)a.play().catch(()=>stopPlayback());}else{stopPlayback();return;}}segmentFrame=requestAnimationFrame(tick);};segmentFrame=requestAnimationFrame(tick);}
function pianoDemo(count){const sampleRate=22050,length=sampleRate*count*5,buffer=new ArrayBuffer(44+length*2),v=new DataView(buffer);const str=(o,s)=>{[...s].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));};str(0,'RIFF');v.setUint32(4,36+length*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sampleRate,true);v.setUint32(28,sampleRate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,length*2,true);const notes=[60,62,64,67,64,62,60,62,64,60];for(let i=0;i<length;i++){const t=i/sampleRate,n=Math.floor(t/.5)%notes.length,nt=t%.5,f=440*2**((notes[n]-69)/12),env=Math.min(1,nt/.015)*Math.exp(-nt*6),value=(Math.sin(t*2*Math.PI*f)+.25*Math.sin(t*4*Math.PI*f))*env*.2;v.setInt16(44+i*2,Math.round(value*32767),true);}return new Blob([buffer],{type:'audio/wav'});}
async function loadAudio(){const ticket=++audioLoading;const id=currentId;localAudio=false;if(audioURL)URL.revokeObjectURL(audioURL);audioURL=null;$('song-audio').removeAttribute('src');$('song-audio').load();$('audio-controls').hidden=true;$('audio-name').textContent='正在读取音频…';let saved;try{saved=await dbCall('audio','get',id);}catch{}if(ticket!==audioLoading||id!==currentId)return;if(saved){setAudio(saved.blob,saved.name,true);}else if(song().demo){setAudio(pianoDemo(song().lines.length),'原创钢琴旋律 · 可替换为你自己的音频',false);}else{$('audio-name').textContent='导入这首歌的音频，按句循环跟唱。';updateMode();}}
function setAudio(blob,name,uploaded){if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(blob);$('song-audio').src=audioURL;$('audio-controls').hidden=false;$('audio-name').textContent=name;localAudio=uploaded;updateMode();}
$('song-audio').addEventListener('error',()=>{if(audioURL){setStatus('无法读取该音频。请使用设备支持的 MP3、M4A 或 WAV 文件。');$('audio-name').textContent='音频格式不受支持，请重新导入。';}});
$('song-audio').addEventListener('ended',()=>{if(segmentActive&&looping){$('song-audio').currentTime=line().start;$('song-audio').play().catch(()=>stopPlayback());}else if(segmentActive)stopPlayback();});
$('song-audio').addEventListener('pause',()=>{if(segmentActive&&$('song-audio').paused&&!$('song-audio').ended){segmentActive=false;cancelAnimationFrame(segmentFrame);setPlaying(false);}});
$('song-audio').addEventListener('loadedmetadata',()=>{const duration=$('song-audio').duration;if(Number.isFinite(duration)){ $('segment-start').max=duration;$('segment-end').max=duration; }});
$('audio-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;e.target.value='';if(file.size>120*1024*1024){toast('请选择小于 120 MB 的音频文件。');return;}stopPlayback();cancelRecording();audioLoading++;const id=currentId;setAudio(file,file.name,true);try{await dbCall('audio','put',{id,blob:file,name:file.name});toast('音频已保存在当前浏览器。');}catch{toast('音频已加载，但未能保存。请保持页面打开。');}};
function saveSegment(){stopPlayback();const start=Number($('segment-start').value),end=Number($('segment-end').value);if(!$('segment-start').value||!$('segment-end').value||!validSegment(start,end,$('song-audio').duration)){toast('时间段需在音频范围内，终点必须晚于起点。');return;}Object.assign(line(),{start,end});persist();toast('本句时间段已保存：'+start.toFixed(1)+'–'+end.toFixed(1)+' 秒');}
function cancelRecording(){recordingRequest++;if(recorder&&recorder.state!=='inactive')recorder.stop();}
function recordingExtension(type){return type.includes('mp4')?'.m4a':type.includes('ogg')?'.ogg':'.webm';}
async function toggleRecording(){if(recorder&&recorder.state==='recording'){cancelRecording();return;}stopPlayback();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){setStatus('当前浏览器无法录音。请通过 HTTPS 在手机 Safari 或 Chrome 打开。');return;}const ticket=++recordingRequest,meta={title:song().title,text:plainText(line().text),songId:currentId,line:lineIndex},button=$('record');button.disabled=true;setStatus('正在请求麦克风权限…');let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(ticket!==recordingRequest){stream.getTracks().forEach(t=>t.stop());return;}const types=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'];const mimeType=types.find(t=>MediaRecorder.isTypeSupported(t));const localRecorder=new MediaRecorder(stream,mimeType?{mimeType}:undefined);recorder=localRecorder;const chunks=[];let failed=false;localRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};localRecorder.onerror=()=>{failed=true;setStatus('录音中断，请检查麦克风后重试。');};recordStarted=Date.now();recordingClock=setInterval(()=>{const elapsed=Math.floor((Date.now()-recordStarted)/1000);$('record-timer').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(elapsed%60).padStart(2,'0');if(elapsed>=120)cancelRecording();},500);localRecorder.onstop=async()=>{clearInterval(recordingClock);stream.getTracks().forEach(t=>t.stop());if(recorder===localRecorder)recorder=null;button.classList.remove('recording');button.querySelector('span').textContent='录下我的练唱';$('record-timer').textContent='';if(failed||!chunks.length)return;const blob=new Blob(chunks,{type:localRecorder.mimeType||chunks[0].type}),created=Date.now(),saved={...meta,blob,created,id:'rec-'+created+'-'+Math.random().toString(36).slice(2,7)};let persisted=true;try{await dbCall('recordings','put',saved);}catch{persisted=false;}if(currentId===meta.songId&&lineIndex===meta.line){if(recordingURL)URL.revokeObjectURL(recordingURL);recordingURL=URL.createObjectURL(blob);$('recording-player').src=recordingURL;$('download-recording').href=recordingURL;$('download-recording').download='kotoba-'+created+recordingExtension(blob.type);$('latest-recording').hidden=false;setStatus(persisted?'录音已保存。回听后，对照原唱练习发音和节奏。':'录音未能保存，请先下载本次录音。');}else toast(persisted?'上一句的录音已保存到「练唱录音」。':'上一句录音未能保存，请检查浏览器存储。');if(currentView==='recordings')renderRecordings();};localRecorder.start();button.classList.add('recording');button.querySelector('span').textContent='停止并保存';setStatus('正在录音，最长 2 分钟。建议戴耳机，减少伴奏串音。');}catch(error){stream?.getTracks().forEach(t=>t.stop());setStatus(error.name==='NotAllowedError'?'麦克风权限未开启，请在浏览器设置中允许后重试。':'无法开启麦克风：'+error.name);}finally{button.disabled=false;}}
function openEditor(kind){stopPlayback();cancelRecording();editing=kind;$('editor-title').textContent=kind==='new'?'添加歌曲':kind==='edit'?'编辑本句':'添加一句歌词';$('song-fields').hidden=kind!=='new';$('edit-title').required=kind==='new';$('edit-title').value=kind==='new'?'':song().title;$('edit-artist').value=kind==='new'?'':song().artist;$('edit-lang').value=song().lang;const l=kind==='edit'?line():null;for(const key of ['text','reading','translation','note'])$('edit-'+key).value=l?.[key]||'';$('edit-words').value=(l?.words||[]).map(w=>[w.term,w.reading,w.meaning,w.usage,w.example,w.exampleTranslation].join(' | ')).join('\n');$('editor-error').textContent='';$('editor').showModal();}
$('editor-form').onsubmit=e=>{e.preventDefault();const words=$('edit-words').value.split('\n').filter(x=>x.trim()).map(row=>{const parts=row.split('|').map(x=>x.trim());return Object.fromEntries(['term','reading','meaning','usage','example','exampleTranslation'].map((k,i)=>[k,parts[i]||'']));});const l={text:$('edit-text').value.trim(),reading:$('edit-reading').value.trim(),translation:$('edit-translation').value.trim(),note:$('edit-note').value.trim(),words,start:editing==='edit'?line().start:0,end:editing==='edit'?line().end:null};try{const candidate=validateSong({id:editing==='new'?'custom-'+Date.now():song().id,title:editing==='new'?$('edit-title').value:song().title,artist:editing==='new'?$('edit-artist').value:song().artist,lang:editing==='new'?$('edit-lang').value:song().lang,lines:[l]});if(editing==='new'){allSongs.push(candidate);currentId=candidate.id;lineIndex=0;loadAudio();}else if(editing==='edit'){song().lines[lineIndex]=candidate.lines[0];delete mastered[currentId+':'+lineIndex];}else if(song().titleOnly){song().lines=candidate.lines;song().titleOnly=false;lineIndex=0;}else{if(song().lines.length>=150)throw new Error('每首歌曲最多添加 150 句。');song().lines.push(candidate.lines[0]);lineIndex=song().lines.length-1;}
  persist();$('editor').close();renderLine();showView('learn');toast('学习卡已保存。');}catch(error){$('editor-error').textContent=error.message;}};
$('import-json').onclick=()=>$('json-input').click();$('json-input').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>2*1024*1024){toast('资料文件不能超过 2 MB。');return;}try{const data=JSON.parse(await f.text()),s=validateSong({...data,id:'custom-'+Date.now()});allSongs.push(s);persist();chooseSong(s.id);toast('学习资料已导入，接下来可以导入对应音频。');}catch(error){toast('导入失败：'+error.message);}};
$('export-song').onclick=()=>{const s=song();const blob=new Blob([JSON.stringify({title:s.title,artist:s.artist,lang:s.lang,lines:s.lines},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='kotoba-study.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('add-song').onclick=()=>openEditor('new');$('choose-song').onclick=()=>showView('library');$('edit-line').onclick=()=>openEditor('edit');$('append-line').onclick=()=>openEditor('append');$('prepare-song').onclick=()=>openEditor('append');$('try-demo').onclick=()=>chooseSong('demo-ja');$('prev-line').onclick=()=>changeLine(lineIndex-1);$('next-line').onclick=()=>changeLine(lineIndex+1);
$('close-editor').onclick=()=>$('editor').close();$('cancel-editor').onclick=()=>$('editor').close();$('toggle-reading').onclick=()=>{showReading=!showReading;$('toggle-reading').classList.toggle('active',showReading);$('toggle-reading').setAttribute('aria-pressed',String(showReading));renderLine();};$('toggle-translation').onclick=()=>{showTranslation=!showTranslation;$('toggle-translation').classList.toggle('active',showTranslation);$('toggle-translation').setAttribute('aria-pressed',String(showTranslation));$('translation-wrap').hidden=!showTranslation;};
$('master-line').onclick=()=>{const key=currentId+':'+lineIndex;mastered[key]=!mastered[key];persist();renderLine();};$('save-word').onclick=()=>{const idx=favorites.findIndex(w=>w.term===currentWord.term&&w.lang===song().lang);if(idx>=0)favorites.splice(idx,1);else favorites.push({...currentWord,lang:song().lang,songTitle:song().title});persist();updateFavorite();toast(idx>=0?'已取消收藏。':'已添加到「收藏的词」。');};$('speak-word').onclick=()=>{const w=currentWord;let text=w.term;if(song().lang==='ja-JP'&&w.term==='を')text='お';if(song().lang==='ja-JP'&&w.term==='へ')text='え';speak(text,song().lang);};
$('mode-read').onclick=()=>{stopPlayback();mode='read';updateMode();setStatus('');};$('mode-song').onclick=()=>{stopPlayback();mode='song';updateMode();setStatus('');};$('listen').onclick=()=>{if(recorder?.state==='recording'){setStatus('请先停止录音，再播放示范。');return;}if(playing){stopPlayback();return;}if(mode==='read')speak(plainText(line().text),song().lang,true);else startSegment();};$('loop').onclick=()=>{looping=!looping;$('loop').setAttribute('aria-pressed',String(looping));};$('speed').onchange=()=>{if(playing)stopPlayback();};$('record').onclick=toggleRecording;$('save-segment').onclick=saveSegment;$('mark-start').onclick=()=>$('segment-start').value=$('song-audio').currentTime.toFixed(2);$('mark-end').onclick=()=>$('segment-end').value=$('song-audio').currentTime.toFixed(2);
